functions.validateDateAndFireSearch:
function validateDateAndFireSearch() {

		//Declare
		var startdatevalue = $("#fromOrderDate").val();
		//Declare
		var enddatevalue = $("#toOrderDate").val();
		//Check
		if (startdatevalue == '' || enddatevalue == '') {
			//Out
			window.parent.showAlert('From Date and To Date is mandatory');  // VE-53935 S-E
			//Return
			return false;
		}
		//Declare the Date Format
	    var format="MM/DD/YYYY hh:mm a";
		//Parse
	    fromDate = new Date(Date.parse(startdatevalue, "MM/DD/YYYY hh:mm a"));
		//Get
		fromDate /= 24*60*60*1000;
		//Parse
	    toDate = new Date(Date.parse(enddatevalue, "MM/DD/YYYY hh:mm a"));
		//Get
	    toDate /= 24*60*60*1000;
		//Get the difference
	    var diff = toDate - fromDate ;
		//Declare
	    var one_day=1; 
	    //Get the difference in Days
	    var days_diff =  Math.round(diff/one_day);
	    //Check
	    if(days_diff > 1){
	    	//Out
			window.parent.showAlert('You are allowed to view data of maximum 1 Day difference only.');  // VE-53935 S-E
			//Return
			return false;
	    }

		//Fire
		updateAllStats();
	}
